package org.pocketsurf.browser

import android.view.KeyEvent
import android.view.View
import android.view.ViewGroup
import android.widget.TextView
import org.junit.Assert.*
import org.junit.Before
import org.junit.Test
import org.junit.runner.RunWith
import org.robolectric.*
import org.robolectric.annotation.Config

@org.robolectric.annotation.GraphicsMode(org.robolectric.annotation.GraphicsMode.Mode.NATIVE)
@RunWith(RobolectricTestRunner::class)
@Config(sdk=[33],qualifiers="w960dp-h540dp-land-mdpi")
class SetupActivityTest {
 private val prefs get()=RuntimeEnvironment.getApplication().getSharedPreferences("browser",0)
 @Before fun clear(){prefs.edit().clear().commit()}
 private fun all(v:View):List<View> = listOf(v)+if(v is ViewGroup)(0 until v.childCount).flatMap{all(v.getChildAt(it))}else emptyList()
 private fun views(a:SetupActivity)=all(a.window.decorView)
 private fun settle(a:SetupActivity){repeat(3){views(a).forEach{it.forceLayout()};a.window.decorView.apply{measure(View.MeasureSpec.makeMeasureSpec(960,View.MeasureSpec.EXACTLY),View.MeasureSpec.makeMeasureSpec(540,View.MeasureSpec.EXACTLY));layout(0,0,960,540)};TestFrameClock.advance(java.time.Duration.ofMillis(16))}}
 private fun click(a:SetupActivity,label:String){views(a).filterIsInstance<TextView>().first{it.text.toString()==label}.performClick();settle(a)}
 private fun desc(a:SetupActivity,value:String)=views(a).first{it.contentDescription?.toString()==value}
 private fun key(a:SetupActivity,k:Int){a.dispatchKeyEvent(KeyEvent(KeyEvent.ACTION_DOWN,k));a.dispatchKeyEvent(KeyEvent(KeyEvent.ACTION_UP,k));settle(a)}
 @Test fun skipIsOptionalAndAddsNoWebsitesOrRuntimePermissions(){val c=Robolectric.buildActivity(SetupActivity::class.java).setup().visible();val a=c.get();click(a,"Skip setup");assertTrue(a.isFinishing);assertTrue(prefs.getBoolean(SetupActivity.COMPLETE,false));assertEquals("google",SearchEngines.resolve(prefs).id);assertTrue(StartPageStore(prefs).shortcuts().isEmpty());assertNull(Shadows.shadowOf(a).lastRequestedPermission);c.pause().stop().destroy()}
 @Test fun engineAndExplicitPinsSaveOnlyAtCompletion(){val c=Robolectric.buildActivity(SetupActivity::class.java).setup().visible();val a=c.get();desc(a,"Search engine: Brave Search").performClick();assertEquals("google",SearchEngines.resolve(prefs).id);click(a,"Continue");desc(a,"Pin website: YouTube").performClick();assertTrue(StartPageStore(prefs).shortcuts().isEmpty());click(a,"Start browsing");assertEquals("brave",SearchEngines.resolve(prefs).id);assertEquals(listOf("https://www.youtube.com/"),StartPageStore(prefs).shortcuts().map{it.url});assertTrue(prefs.getBoolean(SetupActivity.COMPLETE,false));c.pause().stop().destroy()}
 @Test fun controllerCanCompleteAndBackTracksWizardHierarchy(){val c=Robolectric.buildActivity(SetupActivity::class.java).setup().visible();val a=c.get();key(a,96);assertTrue(views(a).filterIsInstance<TextView>().any{it.text=="Choose pinned bookmarks"});key(a,97);assertTrue(views(a).filterIsInstance<TextView>().any{it.text=="Choose your search engine"});key(a,96);assertTrue(views(a).filterIsInstance<TextView>().any{it.text=="Choose pinned bookmarks"});key(a,96);assertTrue(a.isFinishing);assertTrue(StartPageStore(prefs).shortcuts().isEmpty());c.pause().stop().destroy()}
 @Test fun selectionKeepsFocusOnTheChosenOption(){val c=Robolectric.buildActivity(SetupActivity::class.java).setup().visible();val a=c.get();desc(a,"Search engine: Ecosia").performClick();settle(a);assertEquals("Search engine: Ecosia",a.window.decorView.findFocus()!!.contentDescription);click(a,"Continue");desc(a,"Pin website: Wikipedia").performClick();settle(a);assertEquals("Pin website: Wikipedia",a.window.decorView.findFocus()!!.contentDescription);c.pause().stop().destroy()}
 @Test fun existingPinsAndCustomEngineSurviveSkip(){val engine=SearchEngines.custom("Custom","https://search.test/?q={query}");SearchEngines.select(prefs,engine);StartPageStore(prefs).put("Existing","https://existing.test/");val c=Robolectric.buildActivity(SetupActivity::class.java).setup().visible();click(c.get(),"Skip setup");assertEquals("custom",SearchEngines.resolve(prefs).id);assertEquals("https://existing.test/",StartPageStore(prefs).shortcuts().single().url);c.pause().stop().destroy()}
 @Test fun leftStickAndHatMoveActualNativeFocus(){val c=Robolectric.buildActivity(SetupActivity::class.java).setup().visible();val a=c.get();a.window.decorView.apply{measure(View.MeasureSpec.makeMeasureSpec(960,View.MeasureSpec.EXACTLY),View.MeasureSpec.makeMeasureSpec(540,View.MeasureSpec.EXACTLY));layout(0,0,960,540)}
  fun motion(axis:Int,value:Float):android.view.MotionEvent{val p=android.view.MotionEvent.PointerProperties().apply{id=0};val xy=android.view.MotionEvent.PointerCoords().apply{setAxisValue(axis,value)};return android.view.MotionEvent.obtain(0,0,android.view.MotionEvent.ACTION_MOVE,1,arrayOf(p),arrayOf(xy),0,0,1f,1f,0,0,android.view.InputDevice.SOURCE_JOYSTICK,0)}
  val start=a.window.decorView.findFocus();val stick=motion(android.view.MotionEvent.AXIS_Y,-1f);assertTrue(a.dispatchGenericMotionEvent(stick));stick.recycle();assertNotSame(start,a.window.decorView.findFocus());val middle=a.window.decorView.findFocus();val release=motion(android.view.MotionEvent.AXIS_Y,0f);a.dispatchGenericMotionEvent(release);release.recycle();val hat=motion(android.view.MotionEvent.AXIS_HAT_X,-1f);assertTrue(a.dispatchGenericMotionEvent(hat));hat.recycle();assertNotSame(middle,a.window.decorView.findFocus());c.pause().stop().destroy()
 }
 @Test fun remappedConfirmOperatesTheWizard(){ControllerBindings(prefs).assign(Control.CONFIRM,99);val c=Robolectric.buildActivity(SetupActivity::class.java).setup().visible();key(c.get(),99);assertTrue(views(c.get()).filterIsInstance<TextView>().any{it.text=="Choose pinned bookmarks"});c.pause().stop().destroy()}
 @Suppress("DEPRECATION") @Test fun androidBackAndControllerBackShareHierarchyAndSkipSemantics(){val c=Robolectric.buildActivity(SetupActivity::class.java).setup().visible();val a=c.get();desc(a,"Search engine: Ecosia").performClick();click(a,"Continue");desc(a,"Pin website: YouTube").performClick();a.onBackPressed();settle(a);assertFalse(a.isFinishing);assertTrue(views(a).filterIsInstance<TextView>().any{it.text=="Choose your search engine"});key(a,KeyEvent.KEYCODE_BACK);assertTrue(a.isFinishing);assertTrue(prefs.getBoolean(SetupActivity.COMPLETE,false));assertEquals("google",SearchEngines.resolve(prefs).id);assertTrue(StartPageStore(prefs).shortcuts().isEmpty());c.pause().stop().destroy()}
 @Suppress("DEPRECATION") @Test fun legacyAndroidBackCallbackSkipsInitialSetup(){val c=Robolectric.buildActivity(SetupActivity::class.java).setup().visible();val a=c.get();a.onBackPressed();assertTrue(a.isFinishing);assertTrue(prefs.getBoolean(SetupActivity.COMPLETE,false));c.pause().stop().destroy()}
 @Test fun bookmarksBarIsOptInAndPersistsOnlyOnFinish(){val c=Robolectric.buildActivity(SetupActivity::class.java).setup().visible();val a=c.get();click(a,"Continue");val box=desc(a,"Show bookmarks bar while browsing") as android.widget.CheckBox;assertFalse(box.isChecked);assertFalse(prefs.getBoolean(SetupActivity.BOOKMARKS_BAR,false));box.requestFocus();key(a,96);assertTrue(box.isChecked);assertFalse(prefs.getBoolean(SetupActivity.BOOKMARKS_BAR,false));click(a,"Start browsing");assertTrue(prefs.getBoolean(SetupActivity.BOOKMARKS_BAR,false));c.pause().stop().destroy()}
 @Test fun skippingDiscardsDraftBookmarksBarChange(){val c=Robolectric.buildActivity(SetupActivity::class.java).setup().visible();val a=c.get();click(a,"Continue");desc(a,"Show bookmarks bar while browsing").performClick();key(a,97);click(a,"Skip setup");assertFalse(prefs.getBoolean(SetupActivity.BOOKMARKS_BAR,false));c.pause().stop().destroy()}
 @Test fun bothPagesKeepLegendWithRemappedLabelsAndNoPermissionOrRolePage(){ControllerBindings(prefs).apply{assign(Control.CONFIRM,99);assign(Control.BACK,100)};val c=Robolectric.buildActivity(SetupActivity::class.java).setup().visible();val a=c.get();settle(a)
  fun legend():View { return views(a).first{it.contentDescription?.startsWith("Setup controls:")==true} }
  assertTrue(legend().isShown);assertTrue(legend().contentDescription.toString().contains("X Select"));assertTrue(legend().contentDescription.toString().contains("Y Skip setup"));click(a,"Continue");assertTrue(legend().isShown);assertTrue(legend().contentDescription.toString().contains("Y Back"));assertTrue(views(a).filterIsInstance<TextView>().none{it.text=="Permissions"||it.text=="Default browser"});assertNull(Shadows.shadowOf(a).nextStartedActivity);click(a,"Start browsing");assertTrue(a.isFinishing);assertNull(Shadows.shadowOf(a).lastRequestedPermission);c.pause().stop().destroy()}
 @Test fun everyEngineAndPopularWebsiteHasADecorativeIcon(){val c=Robolectric.buildActivity(SetupActivity::class.java).setup().visible();val a=c.get();for(engine in SearchEngines.entries){val option=desc(a,"Search engine: ${engine.name}") as ViewGroup;assertTrue(all(option).any{it is SiteIconView});assertNotNull(desc(a,"${engine.name} icon"))};click(a,"Continue");for(site in StartPageStore.popular){val option=desc(a,"Pin website: ${site.title}") as ViewGroup;assertTrue(all(option).any{it is SiteIconView});assertNotNull(desc(a,"${site.title} icon"))};c.pause().stop().destroy()}
 @Test fun actualTouchChoosesAndTogglesOnFirstTapWhileLegendStaysVisible(){val c=Robolectric.buildActivity(SetupActivity::class.java).setup().visible();val a=c.get();settle(a)
  fun touch(v:View){val rect=android.graphics.Rect();assertTrue("Touch target must be visible: ${v.contentDescription ?: (v as? TextView)?.text}",v.getGlobalVisibleRect(rect));val now=android.os.SystemClock.uptimeMillis();for(action in listOf(android.view.MotionEvent.ACTION_DOWN,android.view.MotionEvent.ACTION_UP)){val event=android.view.MotionEvent.obtain(now,now+20,action,rect.exactCenterX(),rect.exactCenterY(),0);event.source=android.view.InputDevice.SOURCE_TOUCHSCREEN;a.dispatchTouchEvent(event);event.recycle()};settle(a)}
  touch(desc(a,"Search engine: Brave Search"));assertTrue(desc(a,"Search engine: Brave Search").isSelected);touch(views(a).filterIsInstance<TextView>().first{it.text=="Continue"});assertTrue(views(a).filterIsInstance<TextView>().any{it.text=="Choose pinned bookmarks"});touch(desc(a,"Show bookmarks bar while browsing"));assertTrue((desc(a,"Show bookmarks bar while browsing") as android.widget.CheckBox).isChecked);assertTrue(views(a).first{it.contentDescription?.startsWith("Setup controls:")==true}.isShown);touch(views(a).filterIsInstance<TextView>().first{it.text=="Start browsing"});assertTrue(a.isFinishing);assertTrue(prefs.getBoolean(SetupActivity.BOOKMARKS_BAR,false));assertEquals("brave",SearchEngines.resolve(prefs).id);c.pause().stop().destroy()
 }
 @Test fun refreshingExistingArtworkKeepsSetupSelectionAndFocus(){val c=Robolectric.buildActivity(SetupActivity::class.java).setup().visible();val a=c.get();desc(a,"Search engine: Ecosia").performClick();settle(a);val choice=desc(a,"Search engine: Ecosia");val focused=a.window.decorView.findFocus();val icon=desc(a,"Ecosia icon") as SiteIconView;icon.refresh(android.graphics.Bitmap.createBitmap(16,16,android.graphics.Bitmap.Config.ARGB_8888));settle(a);assertSame(choice,desc(a,"Search engine: Ecosia"));assertTrue(choice.isSelected);assertSame(focused,a.window.decorView.findFocus());assertSame(icon,desc(a,"Ecosia icon"));c.pause().stop().destroy()}
 @Test fun progressStaysAtTopAndUsesTheSelectedAccentOnBothSteps(){prefs.edit().putString("theme","Light").putString("accent","Violet").commit();val c=Robolectric.buildActivity(SetupActivity::class.java).setup().visible();val a=c.get();settle(a);val expected=BrowserTheme.resolve("Light",false,"Violet").accent
  fun check(step:Int){val progress=desc(a,"Setup progress: step $step of 2") as android.widget.ProgressBar;assertEquals(2,progress.max);assertEquals(step,progress.progress);assertEquals(expected,progress.progressTintList!!.defaultColor);val parent=progress.parent as View;assertEquals(parent.paddingTop,progress.top);assertEquals(parent.width-parent.paddingLeft-parent.paddingRight,progress.width);val rect=android.graphics.Rect();assertTrue(progress.getGlobalVisibleRect(rect));assertEquals(progress.height,rect.height());assertTrue(progress.height in 3..6)}
  check(1);click(a,"Continue");check(2);c.pause().stop().destroy()
 }
 @Test fun footerActionsAndBookmarksBarHaveIconsWithoutDuplicatingCheckboxes(){val c=Robolectric.buildActivity(SetupActivity::class.java).setup().visible();val a=c.get();for(title in listOf("Skip setup","Continue")){val action=views(a).filterIsInstance<android.widget.Button>().first{it.text==title};assertTrue(action.compoundDrawablesRelative[0] is SurfIcon)};click(a,"Continue");for(title in listOf("Back","Start browsing")){val action=views(a).filterIsInstance<android.widget.Button>().first{it.text==title};assertTrue(action.compoundDrawablesRelative[0] is SurfIcon)};val checkbox=desc(a,"Show bookmarks bar while browsing") as android.widget.CheckBox;assertNotNull(checkbox.buttonDrawable);assertTrue(checkbox.compoundDrawablesRelative[0] is SurfIcon);assertEquals(1,views(a).filterIsInstance<android.widget.CheckBox>().size);assertTrue(views(a).filterIsInstance<TextView>().none{it.text.toString().contains("favorites",true)});c.pause().stop().destroy()}
}
